SELECT 'gongkao', '倒出同等质量', 'kp-conc-pm-same-mass', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "倒出同等质量互换"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "从 A杯 和 B杯 分别倒出 x 克，互相倒入对方杯中。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲杯浓度20%，乙杯浓度10%。各倒出 10克 给对方……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心结论（必背）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果最后两杯的浓度变得一样了，那么【倒出的质量 x，一定等于公式算的那个特殊值】。这属于高阶公式模型，考场上直接代入差值公式求解。"}]}]}$$ AS jsonb), NULL, '倒出同等质量的核心考点与实战推导。', category_node.id, CAST('["数量关系", "浓度问题", "倒出同等质量"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_conc_pm_same_mass", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
